import { fireEvent, screen, within } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import { renderWithProviders } from "../../tests/utils";
import type { Skill, SkillCatalog, SkillState } from "../../types";
import { SkillSection } from "./SkillSection";

const cardReplace: Skill = {
  id: "card_replace",
  name: "Card Replace",
  description: "Order a replacement card.",
  is_default: false,
  engine_managed: false,
  disabled: false,
  sections: [
    {
      type: "prose",
      segments: [
        { text: "Help the customer with lock_card when needed.", condition: null },
        {
          text: "Lock the card immediately.",
          condition: "session.card_replace.reason == 'stolen'",
        },
      ],
    },
    { type: "ordered_block", block_id: "main" },
  ],
  blocks: {
    main: {
      ordered_block_id: "card_replace__main",
      complete_when: null,
      steps: [{ id: "start", kind: "action" }],
    },
  },
  referenced_skills: ["card_disambiguation"],
  tool_names: ["lock_card"],
  hidden: false,
};

const skillCatalog: SkillCatalog = { card_replace: cardReplace };

const skillState: SkillState = {
  active_skill: {
    skill_id: "card_replace",
    ordered_block_id: "card_replace__main",
    step_id: "start",
  },
  blocks: { card_replace__main: { status: "active" } },
  evaluated_conditions: { "session.card_replace.reason == 'stolen'": false },
  tools: {},
  llm_calls: [],
  memory: {},
  pending_skills: [],
};

describe("SkillSection", () => {
  it("shows an empty state while no skill is active", () => {
    renderWithProviders(<SkillSection />, {
      initialStoreState: { skillCatalog, skillState: { ...skillState, active_skill: null } },
    });
    expect(screen.getByText("No skill is currently active")).toBeInTheDocument();
  });

  it("shows the skill name once, in the pane header", () => {
    renderWithProviders(<SkillSection />, {
      initialStoreState: { skillCatalog, skillState },
    });
    expect(screen.getAllByText("Card Replace")).toHaveLength(1);
    expect(screen.getByText("Order a replacement card.")).toBeInTheDocument();
  });

  it("labels a parked precondition consumer next to the active resolver", () => {
    renderWithProviders(<SkillSection />, {
      initialStoreState: {
        skillCatalog,
        skillState: {
          ...skillState,
          pending_skills: [{ skill_id: "card_replace", name: "Card Replace" }],
        },
      },
    });
    expect(screen.getByTestId("pending-skill-tag")).toHaveTextContent("Pending: Card Replace");
  });

  it("renders prose segments as markdown and highlights tool references", () => {
    renderWithProviders(<SkillSection />, {
      initialStoreState: { skillCatalog, skillState },
    });
    // One inline reference in the prose plus one entry in the tools footer.
    const referenceTags = screen.getAllByTestId("skill-reference-tool");
    expect(referenceTags).toHaveLength(2);
    expect(referenceTags[0]).toHaveTextContent("lock_card");
  });

  it("highlights an @memory mention in the prose as a memory pill", () => {
    const skill: Skill = {
      ...cardReplace,
      sections: [
        {
          type: "prose",
          segments: [
            { text: "Confirm @memory.replacement_reason before submitting.", condition: null },
          ],
        },
      ],
    };
    renderWithProviders(<SkillSection />, {
      initialStoreState: {
        skillCatalog: { card_replace: skill },
        skillState: {
          ...skillState,
          memory: {
            replacement_reason: { value: "lost", source: "llm", scope: "skill", description: null },
          },
        },
      },
    });
    expect(screen.getByTestId("skill-reference-memory")).toHaveTextContent("replacement_reason");
  });

  it("lists the skill's available tools below the document", () => {
    renderWithProviders(<SkillSection />, {
      initialStoreState: { skillCatalog, skillState },
    });
    const footer = screen.getByTestId("skill-available-tools");
    expect(footer).toHaveTextContent("Available tools");
    expect(footer).toHaveTextContent("lock_card");
  });

  it("lists the skill's referenced skills below the tools", () => {
    renderWithProviders(<SkillSection />, {
      initialStoreState: { skillCatalog, skillState },
    });
    const references = screen.getByTestId("skill-references");
    expect(references).toHaveTextContent("References");
    expect(references).toHaveTextContent("card_disambiguation");
  });

  it("marks tools whose gate is inactive as disabled", () => {
    renderWithProviders(<SkillSection />, {
      initialStoreState: {
        skillCatalog,
        skillState: { ...skillState, tools: { lock_card: { active: false } } },
      },
    });
    const footer = screen.getByTestId("skill-available-tools");
    const footerTag = within(footer).getByTestId("skill-reference-tool");
    expect(footerTag).toHaveAttribute("data-disabled");
  });

  it("does not mark tools disabled when their gate is open", () => {
    renderWithProviders(<SkillSection />, {
      initialStoreState: {
        skillCatalog,
        skillState: { ...skillState, tools: { lock_card: { active: true } } },
      },
    });
    const footer = screen.getByTestId("skill-available-tools");
    const footerTag = within(footer).getByTestId("skill-reference-tool");
    expect(footerTag).not.toHaveAttribute("data-disabled");
  });

  it("renders scoped paragraphs as bordered cards with a phrased condition", () => {
    renderWithProviders(<SkillSection />, {
      initialStoreState: { skillCatalog, skillState },
    });
    const scoped = screen.getAllByTestId("skill-prose-segment")[1];
    expect(scoped).toHaveTextContent("If");
    expect(scoped).toHaveTextContent("reason");
    expect(scoped).toHaveTextContent("stolen");
  });

  it("marks if-scoped segments with their condition result", () => {
    renderWithProviders(<SkillSection />, {
      initialStoreState: { skillCatalog, skillState },
    });
    const segments = screen.getAllByTestId("skill-prose-segment");
    expect(segments[0]).not.toHaveAttribute("data-condition-met");
    expect(segments[1]).toHaveAttribute("data-condition-met", "false");
  });

  it("renders ordered blocks as cards with their runtime status", () => {
    renderWithProviders(<SkillSection />, {
      initialStoreState: { skillCatalog, skillState },
    });
    const blockCard = screen.getByTestId("skill-block-card");
    expect(blockCard).toHaveAttribute("data-block-id", "main");
    expect(blockCard).toHaveAttribute("data-status", "active");
    expect(blockCard).toHaveTextContent("ordered_block · main");
  });

  it("expands the block running the active flow with an inline canvas", () => {
    renderWithProviders(<SkillSection />, {
      initialStoreState: { skillCatalog, skillState },
    });
    const blockCard = screen.getByTestId("skill-block-card");
    expect(blockCard).toHaveAttribute("data-expanded", "true");
    expect(screen.getByTestId("skill-block-canvas")).toBeInTheDocument();
  });

  it("collapses inactive blocks and lets the user expand them manually", () => {
    const routingState: SkillState = {
      ...skillState,
      active_skill: { skill_id: "card_replace", ordered_block_id: "card_replace", step_id: null },
      blocks: { card_replace__main: { status: "inactive" } },
    };
    renderWithProviders(<SkillSection />, {
      initialStoreState: { skillCatalog, skillState: routingState },
    });
    const blockCard = screen.getByTestId("skill-block-card");
    expect(blockCard).toHaveAttribute("data-expanded", "false");
    expect(screen.queryByTestId("skill-block-canvas")).not.toBeInTheDocument();

    fireEvent.click(within(blockCard).getByRole("button", { expanded: false }));
    expect(screen.getByTestId("skill-block-card")).toHaveAttribute("data-expanded", "true");
    expect(screen.getByTestId("skill-block-canvas")).toBeInTheDocument();
  });

  it("falls back to raw text when markdown rendering fails", () => {
    // Malformed markdown does not throw in react-markdown; this asserts the
    // happy path renders text content so the boundary is exercised in CI via
    // the component tree at least once.
    renderWithProviders(<SkillSection />, {
      initialStoreState: { skillCatalog, skillState },
    });
    expect(screen.getByTestId("skill-section")).toHaveTextContent(
      "Help the customer with lock_card when needed.",
    );
  });

  describe("time-travel (event replay) to the skill at a selected point", () => {
    const transfer: Skill = {
      id: "transfer",
      name: "Transfer",
      description: "Send money.",
      is_default: false,
      engine_managed: false,
      disabled: false,
      sections: [
        {
          type: "prose",
          segments: [{ text: "Collect the amount to transfer.", condition: null }],
        },
      ],
      blocks: {},
      referenced_skills: [],
      tool_names: [],
      hidden: false,
    };
    const twoSkillCatalog: SkillCatalog = { card_replace: cardReplace, transfer };
    // Live: transfer is the active skill, and its live skill_state carries a
    // condition result we must NOT leak into the historical card_replace view.
    const liveTransferState: SkillState = {
      active_skill: { skill_id: "transfer", ordered_block_id: "transfer__main", step_id: null },
      blocks: {},
      evaluated_conditions: { "session.card_replace.reason == 'stolen'": true },
      tools: {},
      llm_calls: [],
      memory: {
        "card_replace.reason": { value: "lost", source: "llm", scope: "skill", description: null },
      },
    };

    function convEvent(overrides: Record<string, unknown>) {
      return {
        __typename: "ConversationEvent" as const,
        id: "evt",
        metadata: { parseData: undefined },
        timestamp: new Date().toISOString(),
        originalTimestamp: 0,
        slotValue: null,
        ...overrides,
      };
    }

    const skillActivated = convEvent({
      id: "evt-activated",
      conversationEventType: "SKILL_ACTIVATED",
      skillId: "card_replace",
    });

    function stateSelecting(events: unknown[], selectedId: string) {
      const selected = events.find((e) => (e as { id: string }).id === selectedId);
      return {
        skillCatalog: twoSkillCatalog,
        skillState: liveTransferState,
        selectedElement: selected as never,
        conversationList: [
          {
            id: "conv-1",
            reviewed: false,
            startDate: new Date().toISOString(),
            totalNumberOfUserMessages: 0,
            events: events as never,
          },
        ],
      };
    }

    it("renders the earlier skill's document reconstructed at the selection", () => {
      const blockEntered = convEvent({
        id: "evt-block",
        conversationEventType: "ORDERED_BLOCK_ENTERED",
        skillId: "card_replace",
        blockId: "main",
        flowId: "card_replace__main",
        stepId: "start",
      });
      renderWithProviders(<SkillSection />, {
        initialStoreState: stateSelecting([skillActivated, blockEntered], "evt-block"),
      });
      expect(screen.getByText("Card Replace (at selected message)")).toBeInTheDocument();
      expect(screen.getByTestId("skill-section")).toHaveTextContent(
        "Help the customer with lock_card when needed.",
      );
    });

    it("shows the block Active when the block-entered event is selected (screenshot bug)", () => {
      const blockEntered = convEvent({
        id: "evt-block",
        conversationEventType: "ORDERED_BLOCK_ENTERED",
        skillId: "card_replace",
        blockId: "main",
        flowId: "card_replace__main",
        stepId: "start",
      });
      renderWithProviders(<SkillSection />, {
        initialStoreState: stateSelecting([skillActivated, blockEntered], "evt-block"),
      });
      const blockCard = screen.getByTestId("skill-block-card");
      expect(blockCard).toHaveAttribute("data-status", "active");
    });

    it("marks a condition met from reconstructed memory", () => {
      const memorySet = convEvent({
        id: "evt-mem",
        conversationEventType: "MEMORY_SET",
        name: "card_replace.reason",
        value: "stolen",
        skillId: "card_replace",
      });
      renderWithProviders(<SkillSection />, {
        initialStoreState: stateSelecting([skillActivated, memorySet], "evt-mem"),
      });
      const scoped = screen.getAllByTestId("skill-prose-segment")[1];
      // reason == 'stolen' holds against the reconstructed memory, not the live state.
      expect(scoped).toHaveAttribute("data-condition-met", "true");
    });

    it("marks a condition unmet from reconstructed memory", () => {
      const memorySet = convEvent({
        id: "evt-mem",
        conversationEventType: "MEMORY_SET",
        name: "card_replace.reason",
        value: "lost",
        skillId: "card_replace",
      });
      renderWithProviders(<SkillSection />, {
        initialStoreState: stateSelecting([skillActivated, memorySet], "evt-mem"),
      });
      const scoped = screen.getAllByTestId("skill-prose-segment")[1];
      expect(scoped).toHaveAttribute("data-condition-met", "false");
    });

    it("shows the empty state when the selection precedes any skill activity", () => {
      const userMsg = {
        __typename: "Utterance" as const,
        id: "msg-0",
        type: "USER",
        text: "hi",
        metadata: { parseData: undefined },
        rephrase: false,
        rephrasePrompt: null,
        tokens: [],
        timestamp: new Date().toISOString(),
        originalTimestamp: 0,
      };
      const selectedState = stateSelecting([userMsg, skillActivated], "msg-0");
      renderWithProviders(<SkillSection />, {
        initialStoreState: {
          ...selectedState,
          skillState: {
            ...selectedState.skillState,
            pending_skills: [{ skill_id: "card_replace", name: "Card Replace" }],
          },
        },
      });
      // Nothing was active then: the empty state, not the live transfer skill.
      expect(screen.getByText("No skill is currently active")).toBeInTheDocument();
      expect(screen.queryByText("Transfer")).not.toBeInTheDocument();
      expect(screen.queryByTestId("pending-skill-tag")).not.toBeInTheDocument();
    });

    it("returns to the live skill when the selection is cleared", () => {
      renderWithProviders(<SkillSection />, {
        initialStoreState: {
          skillCatalog: twoSkillCatalog,
          skillState: liveTransferState,
          selectedElement: undefined,
        },
      });
      expect(screen.getByText("Transfer")).toBeInTheDocument();
      expect(screen.queryByText(/at selected message/)).not.toBeInTheDocument();
      expect(screen.getByTestId("skill-section")).toHaveTextContent(
        "Collect the amount to transfer.",
      );
    });
  });
});
